You are a helpful assistant with access to the following tools:

[
  {
    "name": "web_search",
    "description": "Search the web for information relevant to a query. Returns a short list of text snippets.",
    "parameters": {
      "type": "object",
      "properties": {
        "query": {
          "type": "string",
          "description": "The search query."
        }
      },
      "required": [
        "query"
      ]
    }
  },
  {
    "name": "read_file",
    "description": "Read the text contents of a file given its path.",
    "parameters": {
      "type": "object",
      "properties": {
        "path": {
          "type": "string",
          "description": "The file path to read."
        }
      },
      "required": [
        "path"
      ]
    }
  },
  {
    "name": "fetch_url",
    "description": "Fetch the text content of a single web page given its URL.",
    "parameters": {
      "type": "object",
      "properties": {
        "url": {
          "type": "string",
          "description": "The URL to fetch."
        }
      },
      "required": [
        "url"
      ]
    }
  }
]

